import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Contracts & OpenAPI 3.1","description":"","frontmatter":{},"headers":[],"relativePath":"en/04-contracts-and-openapi.md","filePath":"en/04-contracts-and-openapi.md"}'),s={name:"en/04-contracts-and-openapi.md"};function i(r,e,p,c,d,l){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="contracts-openapi-3-1" tabindex="-1">Contracts &amp; OpenAPI 3.1 <a class="header-anchor" href="#contracts-openapi-3-1" aria-label="Permalink to &quot;Contracts &amp; OpenAPI 3.1&quot;">​</a></h1><blockquote><p><strong>End-to-End Type Safety and Code Generation</strong><br><em>FastAPI, Pydantic v2, Orval, and TanStack Query.</em></p></blockquote><hr><h2 id="_1-universal-source-of-truth" tabindex="-1">1. Universal Source of Truth <a class="header-anchor" href="#_1-universal-source-of-truth" aria-label="Permalink to &quot;1. Universal Source of Truth&quot;">​</a></h2><p>In SoftForge, the frontend never writes loose types or hardcoded URLs. All network contracts derive directly from the <strong>OpenAPI 3.1.0</strong> specification exported from backend Pydantic models.</p><hr><h2 id="_2-cold-static-extraction-export-openapi-py" tabindex="-1">2. Cold Static Extraction (<code>export_openapi.py</code>) <a class="header-anchor" href="#_2-cold-static-extraction-export-openapi-py" aria-label="Permalink to &quot;2. Cold Static Extraction (`export_openapi.py`)&quot;">​</a></h2><p>No running database or live web server is needed to inspect or export API contracts. The script <code>tools/scripts/export_openapi.py</code> statically instantiates the FastAPI app with an in-memory test engine:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/export_openapi.py</span></span></code></pre></div><p>This updates <code>apps/api/openapi.json</code> in milliseconds.</p><hr><h2 id="_3-automated-frontend-codegen-orval" tabindex="-1">3. Automated Frontend CodeGen (<code>Orval</code>) <a class="header-anchor" href="#_3-automated-frontend-codegen-orval" aria-label="Permalink to &quot;3. Automated Frontend CodeGen (`Orval`)&quot;">​</a></h2><p>Running Orval inside <code>apps/web</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codegen</span></span></code></pre></div><p>Produces:</p><ul><li>TypeScript models in <code>src/api/generated/models/</code>.</li><li>TanStack Query hooks (<code>useQuery</code>, <code>useMutation</code>) for each backend operation.</li><li>Axios client integration with automatic HttpOnly cookie credentials.</li></ul>',16)])])}const k=a(s,[["render",i]]);export{u as __pageData,k as default};
